1	import { db } from "./db";
2	import { sendMail } from "./mailer";
3	import { emails } from "./email-templates";
4	import { appUrl } from "./email-render";
5	import { GAME_DISPLAY, GAME_PORT, type GameFamily } from "./games";
6	import { getSocialLinks } from "./social-links";
7	
8	/**
9	 * Deployment-confirmation email helper.
10	 *
11	 * Sends the "your server is ready" email once a server is provisioned and
12	 * reachable, from BOTH the provision success path (worker) and the admin
13	 * "reconcile from Proxmox" recovery. It is deliberately:
14	 *
15	 *  - TRANSACTIONAL: sent with the CRITICAL `provision_ready` kind so a customer
16	 *    preference can never suppress it (see lib/prefs.ts).
17	 *  - DEDUPED via `EmailLog`: `EmailLog` has no `serverId` column and we add no
18	 *    schema, so the dedupe keys on the template tag + the customer + the
19	 *    server-unique dashboard path that the rendered HTML always contains. Only
20	 *    a prior SENT row blocks a resend, so a failed attempt can still be retried
21	 *    on the next reconcile/provision.
22	 *  - BEST-EFFORT: it runs on the provision money-path, so it swallows every
23	 *    error and NEVER throws into the caller.
24	 */
25	
26	const DEPLOY_TEMPLATE = "server_deployed";
27	
28	type DeployedServer = {
29	  id: string;
30	  hostname: string;
31	  sshPort: number | null;
32	  userId: string;
33	  gamePlanId?: string | null;
34	  plan?: { name?: string | null } | null;
35	  node?: { publicIp?: string | null; region?: string | null } | null;
36	  osTemplate?: { family?: string | null } | null;
37	  portForwards?: { publicPort: number; guestPort: number }[];
38	  dedicatedIp?: { address: string } | null;
39	};
40	
41	type DeployedUser = { email?: string | null } | null | undefined;
42	
43	export async function sendServerDeployedEmail(
44	  passedServer: DeployedServer,
45	  user: DeployedUser
46	): Promise<void> {
47	  try {
48	    const email = user?.email;
49	    if (!email) return;
50	
51	    // Re-read the server from the DB instead of trusting the object we were handed. The provision path
52	    // loads the row BEFORE it allocates the SSH port and the port forwards, so `passedServer.sshPort`
53	    // was null and `portForwards` empty: a shared-NAT customer was emailed `ssh root@IP` with no port,
54	    // which cannot connect (found 2026-10-05). Fall back to the passed object only if the read fails.
55	    const fresh = (await db.server
56	      .findUnique({ where: { id: passedServer.id }, include: { node: true, dedicatedIp: true, portForwards: true, plan: true, osTemplate: true } })
57	      .catch(() => null)) as unknown as DeployedServer | null;
58	    const server: DeployedServer = fresh ?? passedServer;
59	
60	    const dashboardUrl = `${appUrl()}/dashboard/servers/${server.id}`;
61	
62	    // Per-server dedupe (see file header). The dashboard path is server-unique
63	    // and survives EmailLog redaction (only secret query params are stripped).
64	    const already = await db.emailLog.findFirst({
65	      where: {
66	        template: DEPLOY_TEMPLATE,
67	        userId: server.userId,
68	        status: "SENT",
69	        html: { contains: `/dashboard/servers/${server.id}` },
70	      },
71	      select: { id: true },
72	    });
73	    if (already) return;
74	
75	    // ALWAYS the node's public IP + forwarded ssh port — never the internal
76	    // 10.20.x.x address, which is unreachable from outside the host.
77	    const host = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
78	    const sshEndpoint = server.sshPort ? `${host}:${server.sshPort}` : host;
79	
80	    const isGame = !!server.gamePlanId;
81	    const family = server.osTemplate?.family as GameFamily | undefined;
82	    const gameEntry = family && family in GAME_DISPLAY ? GAME_DISPLAY[family] : null;
83	    const gamePort = family && (GAME_PORT as Record<string, { port: number }>)[family];
84	
85	    let gameConnect: string | undefined;
86	    if (isGame && gamePort) {
87	      const dedIp = server.dedicatedIp ?? await db.dedicatedIp.findFirst({ where: { serverId: server.id }, select: { address: true } });
88	      if (dedIp) {
89	        gameConnect = `${dedIp.address}:${gamePort.port}`;
90	      } else {
91	        const fwds = server.portForwards ?? await db.portForward.findMany({ where: { serverId: server.id }, select: { publicPort: true, guestPort: true } });
92	        const fwd = fwds.find((f) => f.guestPort === gamePort.port);
93	        if (fwd) gameConnect = `${host}:${fwd.publicPort}`;
94	      }
95	    }
96	
97	    const tpl = emails.serverDeployed({
98	      hostname: server.hostname,
99	      planName: server.plan?.name ?? "Nxeon",
100	      sshEndpoint,
101	      dashboardUrl,
102	      gameLabel: isGame && gameEntry ? gameEntry.name : undefined,
103	      gameConnect,
104	      gameFamily: isGame && gameEntry ? family : undefined,
105	      region: server.node?.region ?? undefined,
106	      // Only the profiles an operator saved in Admin → Settings (never invented).
107	      socials: (await getSocialLinks().catch(() => [])).map((l) => ({ key: l.key, href: l.href })),
108	    });
109	
110	    await sendMail({
111	      to: email,
112	      subject: tpl.subject,
113	      html: tpl.html,
114	      // Records EmailLog.template = "server_deployed" — the dedupe key above.
115	      template: tpl.template,
116	      userId: server.userId,
117	      // CRITICAL kind → non-suppressible transactional delivery.
118	      kind: "provision_ready",
119	    });
120	  } catch (e) {
121	    console.error("[server-deployed-email] send failed (non-fatal)", e);
122	  }
123	}
